const activeFlags = profilePermissionGroups
  .slice(0, 3)
  .flatMap<string>((group) => [...group.flags]);
const legacyFlags = profilePermissionGroups[3].flags;
export const profilePermissionMessages = Object.fromEntries(
  Object.entries(rows).map(([locale, row]) => {
    if (
      row.ui.length !== uiKeys.length ||
      row.rights.length !== activeFlags.length ||
      row.legacy.length !== legacyFlags.length
    )
      throw new Error(`Incomplete profile permission translation: ${locale}`);
    const entries = row.rights.flatMap((value, index) => {
      const parts = value.split("|");
      if (parts.length !== 2 || parts.some((part) => !part.trim()))
        throw new Error(
          `Invalid profile permission translation: ${locale}/${activeFlags[index]}`,
        );
      return [
        [`permission_${activeFlags[index]}`, parts[0]!],
        [`permission_${activeFlags[index]}Help`, parts[1]!],
      ];
    });
    return [
      locale,
      Object.fromEntries([
        ...uiKeys.map((key, index) => [key, row.ui[index]!]),
        ...entries,
        ...legacyFlags.flatMap((flag, index) => [
          [`permission_${flag}`, row.legacy[index]!],
          [
            `permission_${flag}Help`,
            row.ui[flag === "configEncryption" ? 7 : 5]!,
          ],
        ]),
      ]),
    ];
  }),
);
